enum NotificationCurrencyType {
    STORE_CURRENCY
    SALE_CURRENCY
    CUSTOM_CURRENCY
}

import { type InferSchemaType, type Model, model, models, Schema } from "mongoose";
import { Currency } from "sql";
import { PaymentStatus } from "../types/enums";

const operationalCostStatusItemSchema = new Schema(
	{
		date: { required: true, type: Date },
		status: { enum: PaymentStatus, required: true, type: String },
	},
	{ _id: false },
);

export const OperationalCostSchema = new Schema(
	{
		active: { default: true, type: Boolean },
		category: { required: true, type: String },
		currency: {
			default: Currency.BRL,
			enum: Currency,
			required: true,
			type: String,
		},
		description: { required: true, type: String },
		endDate: { type: Date },
		integrationSetId: { required: true, type: String },
		paymentMethod: { required: true, type: String },
		recurrency: { required: true, type: String },
		startDate: { required: true, type: Date },
		statusArray: { default: [], type: [operationalCostStatusItemSchema] },
		value: { required: true, type: Number },
	},
	{ timestamps: true, versionKey: false },
);

export type OperationalCostDocument = InferSchemaType<typeof OperationalCostSchema>;

export const OperationalCostModel =
	(models.OperationalCost as Model<OperationalCostDocument> | undefined) ||
	model<OperationalCostDocument>("OperationalCost", OperationalCostSchema);

import { type InferSchemaType, type Model, model, models, Schema, type Types } from "mongoose";

export enum PixelEventType {
	PAGE_VIEWED = "page_viewed",
	PRODUCT_VIEWED = "product_viewed",
	PRODUCT_ADDED_TO_CART = "product_added_to_cart",
	PRODUCT_REMOVED_FROM_CART = "product_removed_from_cart",
	CART_VIEWED = "cart_viewed",
	CHECKOUT_STARTED = "checkout_started",
	CHECKOUT_COMPLETED = "checkout_completed",
	CHECKOUT_CONTACT_INFO_SUBMITTED = "checkout_contact_info_submitted",
}

export const PixelEventSchema = new Schema(
	{
		createdAt: { type: Date },
		integrationSetHasVirtualStoreId: { required: true, type: String },
		integrationSetId: { required: true, type: String },
		payload: { type: Object },
		platform: { required: true, type: String },
		productIds: { required: true, type: [Schema.Types.ObjectId] },
		retroactive: { type: Boolean },
		type: { enum: PixelEventType, required: true, type: String },
		updatedAt: { type: Date },
	},
	{},
);

export type PixelEventDocument = Omit<InferSchemaType<typeof PixelEventSchema>, "productIds"> & {
	productIds: Types.ObjectId[];
};

export const PixelEventModel =
	(models.PixelEvent as Model<PixelEventDocument> | undefined) ||
	model<PixelEventDocument>("PixelEvent", PixelEventSchema);

import { type InferSchemaType, type Model, model, models, Schema } from "mongoose";

export enum GoalType {
	REVENUE = "REVENUE",
	PROFIT = "PROFIT",
}

export const GoalSchema = new Schema(
	{
		currency: { required: true, type: String },
		endDate: { required: true, type: Date },
		integrationSetHasVirtualStoreId: { required: true, type: String },
		integrationSetId: { required: true, type: String },
		startDate: { required: true, type: Date },
		type: { enum: GoalType, required: true, type: String },
		value: { required: true, type: Number },
	},
	{ timestamps: true },
);

export type GoalDocument = InferSchemaType<typeof GoalSchema>;

export const GoalModel =
	(models.Goal as Model<GoalDocument> | undefined) || model<GoalDocument>("Goal", GoalSchema);

/** biome-ignore-all assist/source/useSortedKeys: order matters here */

import { type InferSchemaType, type Model, model, models, Schema, type Types } from "mongoose";
import { Currency } from "sql";
import type {
	OrderFinancialDetails,
	OrderTransaction,
	RegionalCountry,
	TotalByCurrency,
} from "../types/order";

export const OrderSchema = new Schema(
	{
		billingAddressId: { required: true, type: String },
		cancelledAt: { type: Date },
		cartToken: { index: true, type: String },
		closedAt: { type: Date },
		confirmationNumber: { type: String },
		confirmed: { type: Boolean },
		contactEmail: { searchIndex: true, type: String },
		currency: { enum: Currency, required: true, type: String },
		customerAddressId: { required: true, type: String },
		customerId: { index: true, required: true, type: String },
		customerName: { required: true, searchIndex: true, type: String },
		description: { default: "", required: true, type: String },
		discountAllocations: { default: [], type: [Schema.Types.Mixed] },
		disputes: { type: Schema.Types.Mixed },
		externalCreatedAt: { index: true, type: Date },
		externalCustomerId: { required: true, type: String },
		externalId: { required: true, type: String },
		externalNumber: { required: true, type: String },
		externalPlatformEntityTracking: { index: true, type: [String] },
		externalSequenceNumber: { type: Number },
		fulfillmentMeta: { type: [Schema.Types.Mixed] },
		integrationSetHasCheckoutId: { index: true, type: String },
		integrationSetHasGatewayId: { index: true, type: String },
		integrationSetHasVirtualStoreId: { index: true, required: true, type: String },
		lineItemsSubtotal: { default: [], type: [Schema.Types.Mixed] },
		manualOverrides: { required: false, type: Schema.Types.Mixed },
		paymentMethod: { index: true, required: true, type: String },
		paymentStatus: { index: true, required: true, type: String },
		phone: { type: String },
		presentmentMoney: { type: Schema.Types.Mixed },
		processedAt: { type: Date },
		productCost: {
			type: [
				{
					cost: { type: Schema.Types.Mixed },
					costId: { type: String },
					costOptionId: { type: String },
					costOptionItemId: { type: String },
					productQuantity: { type: Schema.Types.Mixed },
					products: { type: [String] },
					shipping: { type: Schema.Types.Mixed },
				},
			],
		},
		products: { ref: "Product", required: true, type: [Schema.Types.ObjectId] },
		recoverUrl: { type: String },
		regionalCountry: {
			type: {
				country: { required: true, type: String },
				state: { required: true, type: String },
			},
		},
		shippingTotal: { type: Schema.Types.Mixed },
		shopMoney: { required: true, type: Schema.Types.Mixed },
		srcPlatform: { type: String },
		token: { type: String },
		totalPrice: { type: Schema.Types.Mixed },
		trackingCode: { type: [String] },
		trackingCodeUrl: { type: [String] },
		transactions: { type: Schema.Types.Mixed },
		utm: { required: false, type: Schema.Types.Mixed },
		variants: { ref: "Variant", required: true, type: [Schema.Types.ObjectId] },
	},
	{ timestamps: true },
);

OrderSchema.index({
	_id: 1,
	externalCreatedAt: 1,
	integrationSetHasVirtualStoreId: 1,
	paymentStatus: 1,
});

OrderSchema.index({
	products: 1,
});

OrderSchema.index({
	integrationSetHasVirtualStoreId: 1,
	products: 1,
	externalCreatedAt: 1,
});

export type OrderDocument = Omit<
	InferSchemaType<typeof OrderSchema>,
	| "discountAllocations"
	| "disputes"
	| "lineItemsSubtotal"
	| "manualOverrides"
	| "presentmentMoney"
	| "productCost"
	| "regionalCountry"
	| "shippingTotal"
	| "shopMoney"
	| "totalPrice"
	| "transactions"
	| "utm"
> & {
	lineItemsSubtotal: Array<{
		productId: Types.ObjectId | null;
		variantId: Types.ObjectId | null;
		shopMoney: {
			amount: number;
			currency: Currency;
		};
		presentmentMoney: {
			amount: number;
			currency: Currency;
		};
	}>;
	discountAllocations: Array<{
		productId: Types.ObjectId;
		variantId: Types.ObjectId;
		amount: number;
		currency: Currency;
		discountApplicationIndex: number;
		amount_set: {
			shop_money: {
				amount: number;
				currency_code: Currency;
			};
			presentment_money: {
				amount: number;
				currency_code: Currency;
			};
		};
	}>;
	presentmentMoney: OrderFinancialDetails;
	shopMoney: OrderFinancialDetails;
	shippingTotal: {
		shopMoney: {
			currency: Currency;
			amount: number;
		};
		presentmentMoney: {
			currency: Currency;
			amount: number;
		};
	};
	totalPrice: {
		shopMoney: {
			currency: Currency;
			amount: number;
		};
		presentmentMoney: {
			currency: Currency;
			amount: number;
		};
	};
	productCost: Array<{
		cost?: TotalByCurrency;
		costId: string | null;
		costOptionId: string | null;
		costOptionItemId: string | null;
		productQuantity: Record<string, number>;
		products: string[];
		shipping?: TotalByCurrency;
	}>;
	regionalCountry?: RegionalCountry;
	disputes?: OrderTransaction[];
	transactions?: OrderTransaction[];
	utm?: {
		source?: string;
		campaign?: string;
		medium?: string;
		term?: string;
		content?: string;
	};
	manualOverrides?: {
		revenue?: { currency: Currency; amount: number };
		paymentMethod?: string;
		shipping?: { currency: Currency; amount: number };
		taxes?: { currency: Currency; amount: number };
		fees?: { currency: Currency; amount: number };
		productCost?: { currency: Currency; amount: number };
	};
};

export const OrderModel =
	(models.Order as Model<OrderDocument> | undefined) || model<OrderDocument>("Order", OrderSchema);

import type { Currency } from "sql";

export interface OrderFinancialDetails {
	currency: Currency;
	subtotalValue: number;
	totalValue: number;
	totalDiscounts: number;
	totalTax: number;
}

export type TotalByCurrency = Partial<Record<Currency, number>>;

export interface OrderTransaction {
	amount: number | null;
	currency: Currency | null;
	externalId: string;
	fees: OrderTransactionFee[] | null;
	orderDescription?: string;
	processedAt: Date;
	status: OrderTransactionStatus;
	type: OrderTransactionType;
}

export interface OrderTransactionFee {
	externalId: string;
	fixed: {
		currency: Currency;
		amount: number;
	};
	rate: number;
	type: OrderTransactionFeeType;
	variable: {
		currency: Currency;
		amount: number;
	};
}

export enum OrderTransactionFeeType {
	PROCESSING = "PROCESSING",
	EXCHANGE = "EXCHANGE",
	UNKNOWN = "UNKNOWN",
}

export enum OrderTransactionStatus {
	PAID = "PAID",
	PENDING = "PENDING",
	SCHEDULED = "SCHEDULED",
	SUCCESS = "SUCCESS",
	UNKNOWN = "UNKNOWN",
}

export enum OrderTransactionType {
	CHARGE = "CHARGE",
	DISPUTE_LOST = "DISPUTE_LOST",
	DISPUTE_OPEN = "DISPUTE_OPEN",
	DISPUTE_WON = "DISPUTE_WON",
	REFUND = "REFUND",
	RESERVED = "RESERVED",
	RESERVED_REVERSAL = "RESERVED_REVERSAL",
	RESERVED_WITHDRAWAL = "RESERVED_WITHDRAWAL",
	UNKNOWN = "UNKNOWN",
}

export interface RegionalCountry {
	state: string;
	country: string;
}

import type { Currency } from "sql";
import type { PaymentMethod } from "./prisma";

export type FeesMapping = Map<
	PaymentMethod,
	{
		currency: Currency | undefined;
		exists: boolean;
		fixed: number;
		variable: number;
	}
>;

import { t } from "elysia";
import { CurrencyObj } from "~/shared/types";

export const IncomeGraphData = t.Object({
	fees: CurrencyObj,
	label: t.String(),
	marketingCost: CurrencyObj,
	orders: t.Number(),
	productCost: CurrencyObj,
	profit: CurrencyObj,
	revenue: CurrencyObj,
	taxes: CurrencyObj,
});
export type IncomeGraphData = typeof IncomeGraphData.static;

import { type Cookie, t } from "elysia";
import { Currency } from "sql";
import { UserData, UserPreferences } from "~/modules/users/types";

export * from "./date";
export * from "./pagination";
export * from "./prisma";
export * from "./sorting";

export const AmountCurrency = t.Object({
	amount: t.Number(),
	currency: t.Enum(Currency),
});

export const Cookies = t.Cookie({
	Authorization: t.Optional(t.Union([t.String(), t.Record(t.String(), t.Unknown())])),
	Preferences: t.Optional(t.Union([UserPreferences, t.String(), t.Record(t.String(), t.Unknown())])),
	RefreshToken: t.Optional(t.Union([t.String(), t.Record(t.String(), t.Unknown())])),
	UserData: t.Optional(t.Union([UserData, t.Record(t.String(), t.Unknown()), t.String()])),
});
export type Cookies = typeof Cookies.static;

export const CurrencyObj = t.Partial(t.Record(t.Enum(Currency), t.Number()));
export type CurrencyObj = typeof CurrencyObj.static;

export enum NodeEnv {
	Development = "development",
	Production = "production",
	Staging = "staging",
}

export type SetCookie = Cookie<unknown>["setCookie"];

