import { t } from "elysia";
import { PaymentStatus } from "nosql";
import { Currency } from "sql";
import { PaymentMethod } from "~/shared/types";
import { OrderTransaction } from "./orderTransaction";

const OrderInfoTransaction = t.Omit(OrderTransaction, ["externalId", "orderDescription", "processedAt"]);

export const OrderInfo = t.Object({
	_id: t.String(),
	amount: t.Number(),
	currency: t.Enum(Currency),
	disputes: t.Nullable(t.Array(OrderInfoTransaction)),
	paymentMethod: t.Enum(PaymentMethod),
	paymentStatus: t.Enum(PaymentStatus),
	transactions: t.Nullable(t.Array(OrderInfoTransaction)),
	unitCount: t.Number(),
	virtualStoreId: t.String(),
});
export type OrderInfo = typeof OrderInfo.static;

import { t } from "elysia";
import { Currency } from "sql";
import { OrderTransactionFee } from "./transactionFee";
import { OrderTransactionType } from "./transactionType";

export * from "./transactionFee";
export * from "./transactionType";

export enum OrderTransactionStatus {
	PAID = "PAID",
	PENDING = "PENDING",
	SCHEDULED = "SCHEDULED",
	SUCCESS = "SUCCESS",
	UNKNOWN = "UNKNOWN",
}

export const OrderTransaction = t.Object({
	amount: t.Nullable(t.Number()),
	currency: t.Nullable(t.Enum(Currency)),
	externalId: t.String(),
	fees: t.Nullable(t.Array(OrderTransactionFee)),
	orderDescription: t.Optional(t.String()),
	processedAt: t.Date(),
	status: t.Enum(OrderTransactionStatus),
	type: t.Enum(OrderTransactionType),
});
export type OrderTransaction = typeof OrderTransaction.static;

import { t } from "elysia";
import { AmountCurrency } from "~/shared/types";

export enum OrderTransactionFeeType {
	PROCESSING = "PROCESSING",
	EXCHANGE = "EXCHANGE",
	UNKNOWN = "UNKNOWN",
}

export const OrderTransactionFee = t.Object({
	externalId: t.String(),
	fixed: AmountCurrency,
	rate: t.Number(),
	type: t.Enum(OrderTransactionFeeType),
	variable: AmountCurrency,
});
export type OrderTransactionFee = typeof OrderTransactionFee.static;

export enum OrderTransactionType {
	CHARGE = "CHARGE",
	DISPUTE_LOST = "DISPUTE_LOST",
	DISPUTE_OPEN = "DISPUTE_OPEN",
	DISPUTE_WON = "DISPUTE_WON",
	REFUND = "REFUND",
	RESERVED = "RESERVED",
	RESERVED_REVERSAL = "RESERVED_REVERSAL",
	RESERVED_WITHDRAWAL = "RESERVED_WITHDRAWAL",
	UNKNOWN = "UNKNOWN",
}

export const chargebackTransactionMapping = new Map([
	[OrderTransactionType.DISPUTE_LOST, "lost" as const],
	[OrderTransactionType.DISPUTE_OPEN, "open" as const],
	[OrderTransactionType.DISPUTE_WON, "won" as const],
]);
export const chargebackTransactionTypes = new Set([
	OrderTransactionType.DISPUTE_LOST,
	OrderTransactionType.DISPUTE_OPEN,
	OrderTransactionType.DISPUTE_WON,
]);

export const refundTransactionTypes = new Set([OrderTransactionType.REFUND]);

export const warrantyTransactionTypes = new Set([
	OrderTransactionType.RESERVED,
	OrderTransactionType.RESERVED_REVERSAL,
	OrderTransactionType.RESERVED_WITHDRAWAL,
]);

