export interface MarketingCostPerAccount {
	id: string;
	totalSpend: number;
}

import { type InferSchemaType, type Model, model, models, Schema, type Types } from "mongoose";
import { Currency } from "sql";
import { v4 as uuidv4 } from "uuid";
import { CostType } from "../types/enums";

export const MarketingExpensesSchema = new Schema(
	{
		adAccountExternalId: { type: String },
		adAccountName: { type: String },
		conversionCost: { type: Number },
		cpa: { type: Number },
		currency: { enum: Currency, index: true, required: true, type: String },
		dailySpend: { type: [Schema.Types.Mixed] },
		description: { type: String },
		disabledProducts: { ref: "Product", type: [Schema.Types.ObjectId] },
		endDate: { required: true, type: Date },
		externalId: { type: String },
		integrationSetId: { default: uuidv4, required: true, type: String },
		isManual: { required: true, type: Boolean },
		marketingAccountId: { type: String },
		marketingPlatformId: { type: Number },
		name: { required: true, type: String },
		orders: { ref: "Order", type: Schema.Types.ObjectId },
		products: { ref: "Product", type: [Schema.Types.ObjectId] },
		revenue: { type: Number },
		roas: { type: Number },
		spend: { required: true, type: Number },
		startDate: { required: true, type: Date },
		type: { enum: CostType, type: String },
	},
	{ timestamps: true },
);

MarketingExpensesSchema.index({
	adAccountExternalId: 1,
	integrationSetId: 1,
});

MarketingExpensesSchema.index({
	externalId: 1,
});

MarketingExpensesSchema.index({
	products: 1,
});

export type MarketingExpensesDocument = Omit<
	InferSchemaType<typeof MarketingExpensesSchema>,
	"disabledProducts"
> & {
	disabledProducts: Types.ObjectId[];
};

export const MarketingExpensesModel =
	(models.MarketingExpenses as Model<MarketingExpensesDocument> | undefined) ||
	model<MarketingExpensesDocument>("MarketingExpenses", MarketingExpensesSchema);

