import { TotalByCurrencyWrapped } from "@shared/types";
import { DayOfWeek, DayPeriod } from ".";

export interface DashboardGraphTaxes {
	marketing: Record<string, TotalByCurrencyWrapped>;
	revenue: TotalByCurrencyWrapped;
}

export interface DashboardGraphData {
	count: number;
	marketingCost: TotalByCurrencyWrapped;
	productCost: TotalByCurrencyWrapped;
	profit: TotalByCurrencyWrapped;
	total: TotalByCurrencyWrapped;
}

export interface DashboardGraphDataWithFees extends DashboardGraphData {
	fees: TotalByCurrencyWrapped;
	taxes?: DashboardGraphTaxes;
}

export interface SalesByRegionData {
	[region: string]: {
		state: string;
		country: string;
		total: TotalByCurrencyWrapped;
		count: number;
	};
}

export type SalesPerDayOfWeek = Record<DayOfWeek, DashboardGraphData>;
export type SalesPerDayPeriod = Record<DayPeriod, DashboardGraphDataWithFees>;
export type SalesPerHour = Record<number, DashboardGraphDataWithFees>;

import { OrderMetrics, OrderPaymentStats } from "@modules/orders";
import { ByCurrencyWithCount, TotalByCurrency } from "@shared/types";

export * from "./graphs";

export interface DashboardTaxes {
	marketing: Record<string, TotalByCurrency>;
	revenue: TotalByCurrency;
}

export class DashboardInfo extends OrderMetrics<DashboardTaxes> {
	abandonedCarts!: ByCurrencyWithCount;
	operational!: TotalByCurrency;
	ordersDetails!: Omit<OrderPaymentStats[string], "orderInfo">;
}

export interface MultiStoreDashboardInfo extends DashboardInfo {
	perStore?: Record<string, DashboardInfo>;
}

export const daysOfWeek = [
	"sunday",
	"monday",
	"tuesday",
	"wednesday",
	"thursday",
	"friday",
	"saturday",
] as const;
export type DayOfWeek = (typeof daysOfWeek)[number];
export type DayPeriod = "morning" | "afternoon" | "evening" | "night";

export class IncomeInfo {
	count!: number;
	endDate!: Date;
	fees!: TotalByCurrency;
	marketingCost!: TotalByCurrency;
	productCost!: TotalByCurrency;
	revenue!: TotalByCurrency;
	startDate!: Date;
}

