import { ApiProperty } from "@nestjs/swagger";
import { Expose } from "class-transformer";
import { Allow, IsObject, IsOptional } from "class-validator";
import { Currency } from "sql";
import { PaymentMethod, PaymentStatus } from "./enum";

export interface ByCurrencyWithCount {
	byCurrency: CurrencyAndTotalWithCount;
	count: number;
}

export interface ByCurrencyWithCountAndUnitCount extends ByCurrencyWithCount {
	unitCount: number;
}

export type ByPaymentMethod = Partial<Record<PaymentMethod, ByPaymentStatusWrapped>>;
export interface ByPaymentMethodWrapped {
	byPaymentMethod: ByPaymentMethod;
}

export type ByPaymentStatus = Partial<Record<PaymentStatus, ByCurrencyWithCountAndUnitCount>>;
export interface ByPaymentStatusWrapped {
	byPaymentStatus: ByPaymentStatus;
}

export type CurrencyAndTotal = Partial<Record<Currency, Omit<TotalWithCount, "count">>>;
export type CurrencyAndTotalWithCount = Partial<Record<Currency, TotalWithCount>>;

export type TotalByCurrency = Partial<Record<Currency, number>>;

export class TotalByCurrencyWrapped {
	@ApiProperty({
		properties: Object.fromEntries(Object.values(Currency).map(currency => [currency, { type: "number" }])),
		type: "object",
	})
	@Allow()
	@Expose()
	@IsOptional()
	@IsObject()
	byCurrency!: TotalByCurrency;
}

export interface TotalWithCount {
	total: number;
	count: number;
}

import { type InferSchemaType, type Model, model, models, Schema, type Types } from "mongoose";
import { v4 as uuidv4 } from "uuid";
import { Platform } from "../types/enums";

export const AdSchema = new Schema(
	{
		adAccountId: { default: uuidv4, required: true, type: String },
		adSetExternalId: { required: true, type: String },
		adSetId: { required: true, type: String },
		boundProducts: { ref: "Product", required: true, type: [Schema.Types.ObjectId] },
		boundVariants: { ref: "Variant", required: true, type: [Schema.Types.ObjectId] },
		businessAccountId: { default: uuidv4, required: true, type: String },
		campaignExternalId: { required: true, type: String },
		campaignId: { required: true, type: String },
		externalCreatedAt: { required: true, type: Date },
		externalId: { required: true, type: String },
		externalStatus: { required: true, type: String },
		integrationSetHasMarketingPlatformId: { default: uuidv4, required: true, type: String },
		integrationSetId: { default: uuidv4, required: true, type: String },
		name: { required: true, type: String },
		platform: { enum: Platform, required: true, type: String },
		platformId: { required: true, type: Number },
		status: { required: true, type: String },
	},
	{ timestamps: true },
);

export type AdDocument = Omit<InferSchemaType<typeof AdSchema>, "boundProducts" | "boundVariants"> & {
	boundProducts: Types.ObjectId[];
	boundVariants: Types.ObjectId[];
};

export const AdModel = (models.Ad as Model<AdDocument> | undefined) || model<AdDocument>("Ad", AdSchema);

