import { Prop, Schema, SchemaFactory } from "@nestjs/mongoose";
import { PaymentStatus } from "@shared/types";
import { HydratedDocument } from "mongoose";
import { Currency } from "sql";

export type OperationalCostDocument = HydratedDocument<OperationalCost>;

@Schema({ timestamps: true, versionKey: false })
export class OperationalCost {
	@Prop({ required: true })
	integrationSetId!: string;

	@Prop({ required: true })
	recurrency!: string;

	@Prop({ required: true })
	description!: string;

	@Prop({ required: true })
	startDate!: Date;

	@Prop()
	endDate!: Date;

	@Prop({ required: true })
	category!: string;

	@Prop({ default: [] })
	statusArray!: { date: Date; status: PaymentStatus }[];

	@Prop({ default: true })
	active!: boolean;

	@Prop({ required: true })
	paymentMethod!: string;

	@Prop({ required: true })
	value!: number;

	@Prop({
		default: Currency.BRL,
		enum: Currency,
		required: true,
		type: String,
	})
	currency!: Currency;
}

export const OperationalCostSchema = SchemaFactory.createForClass(OperationalCost);

