/* ────────────────────────────────────────
   GRADIENT BOX — independently overridable fill + border layers.

   Three utilities work together:
     gradient-box           static. Does the composition + clip + border carrier.
     gradient-bg-[…]        sets only --tw-gradient-bg (the fill linear-gradient).
     gradient-border-[…]    sets only --tw-gradient-border (the border overlay).

   Only ONE rule writes `background-image` (the static gradient-box). The
   parametrized utilities only assign CSS vars. This means consumers can
   override one layer in isolation without re-specifying the other:

     gradient-box gradient-bg-[c1,c2] gradient-border-[c3,c4]
       focus:gradient-border-[c5,c6]      // changes only the border on focus

   Color stops are spelled out at the call site (typically derived from
   fundamental tokens via oklch(from var(--foreground) l c h / α)). Reusable
   presets live in src/lib/surface-variants.ts.
   ──────────────────────────────────────── */

/* Make --tw-gradient-bg / --tw-gradient-border non-inheriting. Without this,
   the vars cascade from any ancestor that set them (e.g. a Card wrapping
   another gradient-box element), so a nested element with `gradient-box` but
   no explicit `gradient-bg-*` would paint the outer Card's gradient stretched
   to its own box. Registering with `inherits: false` confines each element to
   its own explicit value (or the initial transparent fallback). */
@property --tw-gradient-bg {
	syntax: "*";
	inherits: false;
	initial-value: linear-gradient(transparent, transparent);
}
@property --tw-gradient-border {
	syntax: "*";
	inherits: false;
	initial-value: linear-gradient(transparent, transparent);
}

@utility gradient-box {
	/* Three layers (top → bottom in paint order):
	     1. fill (clipped to padding-box)  — masks the border alpha inside the body, keeping fill pure
	     2. border (clipped to border-box) — alpha overlay; in the body it's masked by layer 1,
	                                         in the 1px ring it composites over layer 3 → blended tint
	     3. fill (clipped to border-box)   — same gradient as layer 1 but extended into the ring,
	                                         so the alpha border has the fill color as a backdrop to blend with
	   The duplication of --tw-gradient-bg is intentional: layer 1 masks above, layer 3 provides
	   the blend backdrop below. */
	background-image:
		var(--tw-gradient-bg, linear-gradient(transparent, transparent)),
		var(--tw-gradient-border, linear-gradient(transparent, transparent)),
		var(--tw-gradient-bg, linear-gradient(transparent, transparent));
	background-origin: border-box;
	background-clip: padding-box, border-box, border-box;
	border: 1px double transparent;
}

@utility gradient-bg-* {
	--tw-gradient-bg: linear-gradient(--value([*]));
}

@utility gradient-border-* {
	--tw-gradient-border: linear-gradient(--value([*]));
}

