import { useState } from 'react'
import { motion } from 'motion/react'
import { Link, useRouterState } from '@tanstack/react-router'

import { cn } from '@/lib/utils'
import { auth } from '@/lib'
import { useSidebarStore } from '@/components/Navbar/stores/useSidebarStore'
import { Button } from '@/components/ui/button'
import { GradientIcon } from '@/components/ui/gradient-icon'
import type { FileRouteTypes } from '@/routeTree.gen'
import {
	BalanceIcon,
	BkLogoIcon,
	BoxIcon,
	BulbIcon,
	CalculatorIcon,
	CardIcon,
	ChevronRightIcon,
	DocumentSearchIcon,
	EmailIcon,
	EngineIcon,
	GiftIcon,
	GroupIcon,
	HomeIcon,
	ListIcon,
	MegaphoneIcon,
	MoneyBoxIcon,
	MoneyEngineIcon,
	PencilIcon,
	SmsIcon,
	ToolIcon,
	TruckIcon,
	TurnoffIcon,
	UserIcon,
	WhatsappIcon,
} from '@/components/ui/icons'

// Accept any component that renders an SVG — both Tabler icons (with their {color, size, stroke}
// API) and our custom icons (forwardRef'd, full SVGProps) satisfy this signature.
type IconComponent = React.ComponentType<React.ComponentProps<'svg'>>

/** Type-safe route paths generated by TanStack Router. */
type AppRoute = FileRouteTypes['to']

export interface NavigationItem {
	label: string
	icon: IconComponent
	/** Absolute route. If omitted (or `disabled` is true) the item renders as a static, non-clickable row. */
	path?: AppRoute
	/** Coming-soon items: greyed out, no pointer events. */
	disabled?: boolean
	/** Children render nested below the parent when the parent is expanded. */
	children?: NavigationItem[]
}

function getNavigationItems(): NavigationItem[] {
	return [
		{ label: 'Início', icon: HomeIcon, path: '/dashboard' },
		{ label: 'Pedidos', icon: ListIcon, path: '/orders' },
		{
			label: 'Produtos',
			icon: BoxIcon,
			children: [
				{ label: 'Lista de Produtos', icon: BoxIcon, path: '/products' },
				{ label: 'Custos de Produto', icon: MoneyBoxIcon, path: '/products/costs' },
				{ label: 'Kits', icon: GiftIcon, path: '/products/kits' },
			],
		},
		{ label: 'Marketing', icon: MegaphoneIcon, path: '/marketing' },
		{ label: 'Whatsapp', icon: WhatsappIcon, disabled: true },
		{ label: 'Email', icon: EmailIcon, disabled: true },
		{ label: 'SMS', icon: SmsIcon, disabled: true },
		{ label: 'Rastreio', icon: TruckIcon, disabled: true },
		{
			label: 'Financeiro',
			icon: CardIcon,
			children: [
				{ label: 'Custos Operacionais', icon: MoneyEngineIcon, path: '/finance/costs' },
				{ label: 'Detalhes Financeiros', icon: DocumentSearchIcon, path: '/finance/details' },
			],
		},
		{ label: 'Central de ideias', icon: BulbIcon, path: '/ideas' },
		{ label: 'Calculadora', icon: CalculatorIcon, path: '/calculator' },
		{ label: 'Minhas Tarefas', icon: PencilIcon, path: '/tasks' },
		{
			label: 'Configurações',
			icon: EngineIcon,
			children: [
				{ label: 'Integrações', icon: ToolIcon, path: '/settings/integrations' },
				{ label: 'Taxas e Tarifas', icon: BalanceIcon, path: '/settings/fees' },
				{ label: 'Contas da Equipe', icon: GroupIcon, disabled: true },
				{ label: 'Minha Conta', icon: UserIcon, path: '/settings/account' },
			],
		},
	]
}

const TRANSITION = {
	duration: 0.3,
	ease: [0.4, 0, 0.2, 1] as const,
}

export type SidebarProps = React.ComponentProps<'aside'>

export function Sidebar({ className }: SidebarProps) {
	const state = useRouterState()
	const activeRoute = state.location.pathname
	const { isExpanded, setIsExpanded } = useSidebarStore()
	const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({})

	const handleLogout = async () => {
		await auth.signOut()
		window.location.href = '/sign-in'
	}

	const items = getNavigationItems()

	const toggleGroup = (label: string) => setOpenGroups(prev => ({ ...prev, [label]: !prev[label] }))

	return (
		<motion.aside
			className={cn('bg-sidebar flex flex-col py-6 px-3 gap-6 z-30 shrink-0 overflow-y-auto overflow-x-hidden', className)}
			initial={false}
			animate={{ width: isExpanded ? '16rem' : '5rem' }}
			transition={TRANSITION}
			onMouseEnter={() => setIsExpanded(true)}
			onMouseLeave={() => setIsExpanded(false)}
		>
			<LogoSection isExpanded={isExpanded} />

			<nav className="flex flex-col gap-1">
				{items.map(item => (
					<NavigationEntry
						key={item.label}
						item={item}
						isExpanded={isExpanded}
						activeRoute={activeRoute}
						isOpen={!!openGroups[item.label]}
						onToggle={() => toggleGroup(item.label)}
					/>
				))}
			</nav>

			<LogoutSection isExpanded={isExpanded} onLogout={handleLogout} />
		</motion.aside>
	)
}

function LogoSection({ isExpanded }: { isExpanded: boolean }) {
	return (
		<div className="flex items-center gap-2.5 h-10 px-2">
			<GradientIcon icon={BkLogoIcon} className="size-7 text-sidebar-foreground shrink-0" />
			<motion.span
				className="text-lg font-semibold text-sidebar-foreground whitespace-nowrap font-serif tracking-tight"
				initial={false}
				animate={{ opacity: isExpanded ? 1 : 0 }}
				transition={TRANSITION}
			>
				Dash
			</motion.span>
		</div>
	)
}

interface NavigationEntryProps {
	item: NavigationItem
	isExpanded: boolean
	activeRoute?: string
	isOpen: boolean
	onToggle: () => void
	depth?: number
}

/**
 * Top-level entry. Renders either:
 *   - a Link (item has `path`, not disabled),
 *   - a button (item has `children`, toggles its nested list),
 *   - a static row (item has neither — acts as placeholder / disabled).
 */
function NavigationEntry({ item, isExpanded, activeRoute, isOpen, onToggle, depth = 0 }: NavigationEntryProps) {
	const hasChildren = !!item.children && item.children.length > 0
	const isActive = item.path ? activeRoute === item.path || activeRoute?.startsWith(`${item.path}/`) : false

	const sharedRow = (
		<EntryContent
			item={item}
			isExpanded={isExpanded}
			hasChildren={hasChildren}
			isOpen={isOpen}
			depth={depth}
		/>
	)

	const rowClass = cn(
		'flex items-center rounded-lg gap-3 h-10 transition-colors',
		depth === 0 ? 'px-3' : 'pl-9 pr-3',
		item.disabled
			? 'opacity-40 text-sidebar-foreground/70 pointer-events-none'
			: isActive
				? 'bg-[linear-gradient(to_right,oklch(from_var(--sidebar-foreground)_l_c_h_/_0.1),transparent)] text-sidebar-foreground'
				: 'text-sidebar-foreground/70 hover:text-sidebar-foreground hover:bg-[linear-gradient(to_right,oklch(from_var(--sidebar-foreground)_l_c_h_/_0.18),transparent)]',
	)

	if (hasChildren) {
		return (
			<>
				<button
					type="button"
					onClick={item.disabled ? undefined : onToggle}
					className={cn(rowClass, 'w-full text-left cursor-pointer')}
					aria-label={item.label}
					aria-expanded={isOpen}
					title={item.label}
					disabled={item.disabled}
				>
					{sharedRow}
				</button>
				{isOpen && isExpanded && (
					<div className="flex flex-col gap-1 mt-1 mb-2">
						{item.children!.map(child => (
							<NavigationEntry
								key={child.label}
								item={child}
								isExpanded={isExpanded}
								activeRoute={activeRoute}
								isOpen={false}
								onToggle={() => {}}
								depth={depth + 1}
							/>
						))}
					</div>
				)}
			</>
		)
	}

	if (item.path && !item.disabled) {
		return (
			<Link to={item.path} className={rowClass} aria-label={item.label} title={item.label}>
				{sharedRow}
			</Link>
		)
	}

	return (
		<div className={rowClass} aria-label={item.label} title={item.disabled ? `${item.label} — Em breve` : item.label}>
			{sharedRow}
		</div>
	)
}

function EntryContent({
	item,
	isExpanded,
	hasChildren,
	isOpen,
	depth,
}: {
	item: NavigationItem
	isExpanded: boolean
	hasChildren: boolean
	isOpen: boolean
	depth: number
}) {
	return (
